insert into phrases (id, action_id, phrase_fr, phrase_en, phase, niveau, voice_type, audio_url) values
('HK_HK_ROOM_CLEAN_0001', 'HK_ROOM_CLEAN', 'Housekeeping, bonjour. Puis-je entrer ?', 'Housekeeping, good morning. May I come in?', 'Accueil', 'A1', 'STAFF', null),
('HK_HK_ROOM_CLEAN_0002', 'HK_ROOM_CLEAN', 'Je viens pour le service de chambre.', 'I am here for your room service.', 'Information', 'A1', 'STAFF', null),
('HK_HK_ROOM_CLEAN_0003', 'HK_ROOM_CLEAN', 'Souhaitez-vous que je repasse plus tard ?', 'Would you like me to come back later?', 'Service', 'A2', 'STAFF', null),
('HK_HK_ROOM_CLEAN_0004', 'HK_ROOM_CLEAN', 'À quelle heure vous convient-il ?', 'What time suits you?', 'Vérification', 'A2', 'STAFF', null),
('HK_HK_ROOM_CLEAN_0005', 'HK_ROOM_CLEAN', 'Je vais ouvrir les rideaux et aérer la chambre.', 'I will open the curtains and air the room.', 'Service', 'A2', 'STAFF', null),
('HK_HK_ROOM_CLEAN_0006', 'HK_ROOM_CLEAN', 'Je peux prendre vos serviettes utilisées ?', 'May I collect your used towels?', 'Service', 'A2', 'STAFF', null),
('HK_HK_ROOM_CLEAN_0007', 'HK_ROOM_CLEAN', 'Je vais faire le lit maintenant.', 'I will make the bed now.', 'Service', 'A2', 'STAFF', null),
('HK_HK_ROOM_CLEAN_0008', 'HK_ROOM_CLEAN', 'Je reviens dans {time} minutes, d’accord ?', 'I will be back in {time} minutes, is that okay?', 'Information', 'A2', 'STAFF', null),
('HK_HK_ROOM_CLEAN_0009', 'HK_ROOM_CLEAN', 'Oui, vous pouvez entrer.', 'Yes, you may come in.', 'Accueil', 'A1', 'CLIENT', null),
('HK_HK_ROOM_CLEAN_0010', 'HK_ROOM_CLEAN', 'Revenez plus tard, s’il vous plaît.', 'Please come back later.', 'Service', 'A1', 'CLIENT', null),
('HK_HK_ROOM_CLEAN_0011', 'HK_ROOM_CLEAN', 'Pouvez-vous nettoyer la salle de bain aussi ?', 'Could you clean the bathroom as well?', 'Service', 'A2', 'CLIENT', null),
('HK_HK_ROOM_CLEAN_0012', 'HK_ROOM_CLEAN', 'Merci, je serai prêt(e) dans {time} minutes.', 'Thank you, I will be ready in {time} minutes.', 'Information', 'A2', 'CLIENT', null),
('HK_HK_ROOM_CLEAN_0013', 'HK_ROOM_CLEAN', 'Je comprends. Je reprogramme le service à {time} et je le note au système.', 'I understand. I will reschedule the service for {time} and note it in the system.', 'Service', 'B1', 'STAFF', null),
('HK_HK_ROOM_CLEAN_0014', 'HK_ROOM_CLEAN', 'Pour votre confort, je peux effectuer un service rapide maintenant et un service complet plus tard.', 'For your comfort, I can do a quick refresh now and a full service later.', 'Service', 'B1', 'STAFF', null),
('HK_HK_ROOM_CLEAN_0015', 'HK_ROOM_CLEAN', 'Merci pour votre patience. Je vérifie la chambre avant de sortir.', 'Thank you for your patience. I will check the room before I leave.', 'Clôture', 'B1', 'STAFF', null),
('HK_HK_ROOM_CLEAN_0016', 'HK_ROOM_CLEAN', 'Tout est terminé. Y a-t-il autre chose que je puisse faire pour vous ?', 'All done. Is there anything else I can do for you?', 'Clôture', 'B1', 'STAFF', null),
('HK_HK_TURNDOWN_0001', 'HK_TURNDOWN', 'Bonsoir, Housekeeping. Puis-je entrer pour le service couverture ?', 'Good evening, Housekeeping. May I come in for turndown service?', 'Accueil', 'A2', 'STAFF', null),
