('HK_HK_TURNDOWN_0009', 'HK_TURNDOWN', 'Oui, entrez.', 'Yes, come in.', 'Accueil', 'A1', 'CLIENT', null),
('HK_HK_TURNDOWN_0010', 'HK_TURNDOWN', 'Pas ce soir, merci.', 'Not tonight, thank you.', 'Service', 'A1', 'CLIENT', null),
('HK_HK_TURNDOWN_0011', 'HK_TURNDOWN', 'Pouvez-vous apporter une couverture supplémentaire ?', 'Could you bring an extra blanket?', 'Service', 'A2', 'CLIENT', null),
('HK_HK_TURNDOWN_0012', 'HK_TURNDOWN', 'Pouvez-vous baisser la climatisation ?', 'Could you lower the air conditioning?', 'Service', 'A2', 'CLIENT', null),
('HK_HK_TURNDOWN_0013', 'HK_TURNDOWN', 'Bien sûr. Je vous apporte une couverture dans {time} minutes.', 'Of course. I will bring a blanket within {time} minutes.', 'Service', 'B1', 'STAFF', null),
('HK_HK_TURNDOWN_0014', 'HK_TURNDOWN', 'Je comprends. Je note votre préférence et je ne repasserai pas ce soir.', 'I understand. I will note your preference and will not return tonight.', 'Service', 'B1', 'STAFF', null),
('HK_HK_TURNDOWN_0015', 'HK_TURNDOWN', 'Souhaitez-vous que je programme un service couverture à une heure précise demain ?', 'Would you like me to schedule turndown at a specific time tomorrow?', 'Information', 'B1', 'STAFF', null),
