('HK_HK_AMENITIES_0012', 'HK_AMENITIES', 'Merci, c’est parfait.', 'Thank you, that’s perfect.', 'Clôture', 'A1', 'CLIENT', null),
('HK_HK_AMENITIES_0013', 'HK_AMENITIES', 'Bien sûr. Je vous apporte cela dans {time} minutes.', 'Of course. I will bring it within {time} minutes.', 'Service', 'B1', 'STAFF', null),
